pub fn order(areas: &Grid) -> Vec<(usize,usize)> {
    let n = areas.len();
    let mut rights = Vec::new();
    let mut right = n-1;
    while right >= 8 {
        rights.push(right);
        right -= 2;
    }
    rights.extend([5,3,1].iter().copied());
    let mut result = Vec::new();
    for (pair,&right) in rights.iter().enumerate() {
        for index in 0..n {
            let y = if pair%2 == 0 {
                n-1-index
            } else {
                index
            };
            for x in [right,right-1].iter().copied() {
                if areas[y][x] == 0 {
                    result.push((x,y));
                }
            }
        }
    }
    result
}
